@import "tailwindcss";

/* Design system: frontend/DESIGN.md ("editorial broadsheet in a green room").
   Light only. Green is the single chromatic accent; everything else is ink on paper. */

:root {
  --background: #fafffa; /* Bone White: paper canvas, never pure #fff */
  --foreground: #000000; /* Typesetter Ink */
  --press: #121613; /* Press Black: dark sections, footer */
  --slate: #232924; /* Slate Verdant */
  --muted: #516254; /* Newsprint Gray: captions, helper text */
  --sage: #c8d2c8; /* Muted Sage: light text on dark; hairlines on light */
  --line: #d6ded6; /* hairline structure */
  --surface: #f0f6f0; /* quiet tint for hover / selected rows */
  --accent: #2bee4b; /* Highlighter Green: primary action, active underline */
  --moss: #93b799; /* Shadow Moss */
  --echo: #c4e4c9; /* Echo Green */
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-press: var(--press);
  --color-slate: var(--slate);
  --color-muted: var(--muted);
  --color-sage: var(--sage);
  --color-line: var(--line);
  --color-surface: var(--surface);
  --color-accent: var(--accent);
  --color-moss: var(--moss);
  --color-echo: var(--echo);
  --font-sans: var(--font-inter);
  --font-serif: var(--font-display);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-inter), system-ui, sans-serif;
}

/* Small-caps micro-label: nav, buttons, section labels. */
@utility label {
  font-size: 11px;
  line-height: 1.1;
  font-weight: 550;
  letter-spacing: 0.01em;
  text-transform: uppercase;
}

/* Serif display headline: tight leading and tracking read as printed ink. */
@utility display {
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

/* The one filled, saturated button; its shadow is green, never gray. */
@utility btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: var(--accent);
  color: #000;
  padding: 16px 28px;
  font-size: 11px;
  font-weight: 550;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  box-shadow: rgba(16, 94, 29, 0.45) 1px 8px 20px 0;
  &:disabled {
    background: transparent;
    color: var(--muted);
    box-shadow: inset 0 0 0 1px var(--line);
    cursor: not-allowed;
  }
}

/* Secondary action: ink outline, no fill, no shadow. */
@utility btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  border: 1px solid var(--foreground);
  padding: 0 16px;
  font-size: 11px;
  font-weight: 550;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  &:hover:not(:disabled) {
    background: var(--foreground);
    color: var(--background);
  }
  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

:focus-visible {
  outline: 2px solid var(--foreground);
  outline-offset: 2px;
}

/* --- Landing page (/about): layout and motion advice from the taste skill, inside DESIGN.md --- */

body {
  overflow-x: clip; /* full-bleed bands use 100vw; never a sideways scroll */
}

/* Cancel <main>'s padding so the hero owns the first screen and the close meets the footer. */
.landing {
  margin-block: -3rem;
}
@media (min-width: 768px) {
  .landing {
    margin-block: -5rem;
  }
}

/* One idea per screen on a desktop: each section is a screen tall, content top-aligned. Phones grow. */
.screen {
  padding-block: 72px;
}
@media (min-width: 1024px) {
  .screen {
    min-height: 100svh;
    padding-block: 120px 96px;
  }
  .hero-screen {
    min-height: calc(100svh - 4rem); /* below the 64px header */
    padding-top: 96px;
  }
}

/* Edge to edge, content still on the page's left and right lines. */
.dark-band {
  margin-inline: calc(50% - 50vw);
  padding-inline: calc(50vw - 50%);
}

/* The hero enters once on load. */
@keyframes enter {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
.enter {
  animation: enter 0.7s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}
.enter-late {
  animation-delay: 0.15s;
}

/* Hover: cards lift 2px, buttons step and press, underlines draw. */
.lift {
  transition: transform 0.2s ease;
}
.lift:hover {
  transform: translateY(-2px);
}
.press {
  transition: transform 0.15s ease;
}
.press:hover {
  transform: translateY(-1px);
}
.press:active {
  transform: translateY(1px);
}
.draw {
  background: linear-gradient(currentColor, currentColor) left bottom / 100% 1px no-repeat;
  padding-bottom: 2px;
  transition: background-size 0.25s ease;
}
.draw:hover {
  background-size: 0% 1px;
  background-position: right bottom;
}

@media (prefers-reduced-motion: reduce) {
  .enter,
  .lift,
  .press,
  .draw {
    animation: none;
    transition: none;
  }
  .lift:hover,
  .press:hover,
  .press:active {
    transform: none;
  }
}
import type { Metadata } from "next";
import { Instrument_Serif, Inter } from "next/font/google";
import Link from "next/link";
import "./globals.css";

// Stand-ins for DESIGN.md's commercial faces: Inter for TWK Lausanne,
// Instrument Serif for the PP Mondwest display serif.
const inter = Inter({ variable: "--font-inter", subsets: ["latin"] });
const display = Instrument_Serif({
  variable: "--font-display",
  subsets: ["latin"],
  weight: "400",
  style: ["normal", "italic"],
});

export const metadata: Metadata = {
  title: "PitchSwitch",
  description: "Who's a fit, and who has a conflict, from either side of the table. Built on Cala.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${inter.variable} ${display.variable} h-full antialiased`}>
      <body className="flex min-h-full flex-col">
        <header className="border-b border-line print:hidden">
          <div className="mx-auto flex h-16 w-full max-w-[1400px] items-center justify-between px-5 md:px-10">
            <Link href="/" className="text-lg font-semibold tracking-tight">
              Pitch<span className="border-b-2 border-accent">Switch</span>
            </Link>
            <nav className="flex items-center gap-6">
              <Link href="/about" className="label hover:underline hover:underline-offset-4">
                How it works
              </Link>
              <Link href="/prep" className="label hover:underline hover:underline-offset-4">
                Slush prep
              </Link>
              <span className="label hidden text-muted md:inline">Every claim sourced from Cala</span>
            </nav>
          </div>
        </header>
        <main className="mx-auto w-full max-w-[1400px] flex-1 px-5 py-12 md:px-10 md:py-20">
          {children}
        </main>
        <footer className="bg-press text-background print:hidden">
          <div className="mx-auto flex w-full max-w-[1400px] flex-wrap items-center justify-between gap-4 px-5 py-8 md:px-10">
            <span className="label">PitchSwitch</span>
            <span className="label text-sage">Data: Cala · Junction 2026</span>
          </div>
          <div className="h-3 bg-accent" />
        </footer>
      </body>
    </html>
  );
}
import { HomeForm } from "@/components/HomeForm";

export default function Home() {
  return (
    <section>
      <p className="label text-muted">Fundraising, from either side of the table</p>
      <h1 className="display mt-5 max-w-4xl text-5xl sm:text-6xl md:text-8xl">
        Who&apos;s a fit, and who has a <em>conflict</em>.
      </h1>
      <p className="mt-8 max-w-xl text-lg leading-snug text-muted">
        PitchSwitch walks Cala&apos;s graph from a company to its competitors, their rounds and the
        investors behind them, and shows a source for every claim.
      </p>
      <HomeForm />
