"use client";

// Home: "I'm raising / I'm investing" toggle, then pick the entities and go.

import { useRouter } from "next/navigation";
import { useState } from "react";

import { EntityPicker } from "@/components/EntityPicker";
import { formatEuro, parseEuro } from "@/lib/money";
import { checkPath, founderPath } from "@/lib/routes";
import type { EntityRef } from "@/lib/types";

type Mode = "founder" | "investor";

const MODES: { value: Mode; label: string; hint: string }[] = [
  { value: "founder", label: "I'm raising", hint: "Who should I pitch, and who should I skip?" },
  {
    value: "investor",
    label: "I'm investing",
    hint: "Does this startup conflict with my portfolio, and who backed its rivals?",
  },
];

export function HomeForm() {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>("founder");
  const [company, setCompany] = useState<EntityRef | null>(null);
  const [fund, setFund] = useState<EntityRef | null>(null);
  const [startup, setStartup] = useState<EntityRef | null>(null);
  // Optional amount (C18): the raise (founder) or the most the fund puts in (investor).
  const [amountText, setAmountText] = useState({ founder: "", investor: "" });
  const text = amountText[mode];
  const amount = parseEuro(text);
  const amountInvalid = text.trim() !== "" && amount === null;

  const ready = (mode === "founder" ? company !== null : fund !== null && startup !== null) && !amountInvalid;

  function go() {
    if (mode === "founder" && company) router.push(founderPath(company.id, amount));
    if (mode === "investor" && fund && startup) router.push(checkPath(fund.id, startup.id, amount));
  }

  return (
    <div className="mt-14 max-w-xl">
      <div role="radiogroup" aria-label="Mode" className="flex gap-8 border-b border-line">
        {MODES.map((m) => (
          <button
            key={m.value}
            type="button"
            role="radio"
            aria-checked={mode === m.value}
            onClick={() => setMode(m.value)}
            className={`label -mb-px border-b-2 pb-3 transition-colors ${
              mode === m.value
                ? "border-accent text-foreground"
                : "border-transparent text-muted hover:text-foreground"
            }`}
          >
            {m.label}
          </button>
        ))}
      </div>
      <p className="mt-4 text-muted">{MODES.find((m) => m.value === mode)?.hint}</p>

      <div className="mt-10 space-y-8">
        {mode === "founder" ? (
          <EntityPicker
            key="company"
            kind="company"
            label="Your company"
            placeholder="e.g. Sensofusion"
            value={company}
            onChange={setCompany}
            examples={["Sensofusion", "Kelluu", "Stendr"]}
          />
        ) : (
          <>
            <EntityPicker
              key="fund"
              kind="investor"
              label="Your fund"
              placeholder="e.g. Tesi"
              value={fund}
              onChange={setFund}
              examples={["Tesi", "Maki.vc"]}
            />
            <EntityPicker
              key="startup"
              kind="company"
              label="The startup that pitched you"
              placeholder="e.g. NestAI"
              value={startup}
              onChange={setStartup}
              examples={["NestAI", "Stendr"]}
            />
          </>
        )}
        <div>
          <label htmlFor="home-amount" className="label">
            {mode === "founder" ? "Amount you want to raise" : "Most you will fund"}{" "}
            <span className="text-muted normal-case">(optional, EUR)</span>
          </label>
          <input
            id="home-amount"
            value={text}
            onChange={(e) => setAmountText((t) => ({ ...t, [mode]: e.target.value }))}
            placeholder={mode === "founder" ? "e.g. 3M" : "e.g. 500k"}
            inputMode="decimal"
            autoComplete="off"
            aria-invalid={amountInvalid}
            aria-describedby="home-amount-hint"
            className="mt-3 block h-11 w-48 rounded-[5px] border border-line bg-background px-3 text-base outline-none placeholder:text-muted focus:border-foreground aria-[invalid=true]:border-foreground"
          />
          <p id="home-amount-hint" className="mt-2 text-sm text-muted" aria-live="polite">
            {amountInvalid
              ? "Type an amount like 3M, 500k or 3 000 000."
              : amount !== null
                ? `${formatEuro(amount)}: compared with the round sizes in Cala.`
                : mode === "founder"
                  ? "Shows which investors join rounds of your size."
                  : "Shows whether this startup raises rounds your check fits."}
          </p>
        </div>
      </div>

      <button
        type="button"
        onClick={go}
        disabled={!ready}
        className="btn-primary mt-10"
      >
        {mode === "founder" ? "Find who to pitch" : "Check this startup"}
      </button>
    </div>
  );
}
"use client";

// Name → /api/resolve → the user confirms which Cala entity they mean
// (Cala has 5 "Inventure"s, so a match is never taken on name alone).

import { useEffect, useId, useRef, useState } from "react";

import { SlowNotice } from "@/components/SlowNotice";
import { describeError } from "@/lib/errors";
import { resolve } from "@/lib/api";
import { splitMatches } from "@/lib/match";
import type { EntityKind, EntityRef } from "@/lib/types";

type State =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "results"; query: string; items: EntityRef[] };

export interface EntityPickerProps {
  kind: EntityKind;
  label: string;
  placeholder: string;
  value: EntityRef | null;
  onChange: (entity: EntityRef | null) => void;
  examples?: string[];
}

export function EntityPicker({ kind, label, placeholder, value, onChange, examples = [] }: EntityPickerProps) {
  const id = useId();
  const [name, setName] = useState("");
  const [state, setState] = useState<State>({ status: "idle" });
  const [showLoose, setShowLoose] = useState(false);
  const abort = useRef<AbortController | null>(null);

  useEffect(() => () => abort.current?.abort(), []);

  async function search(query: string) {
    const q = query.trim();
    if (!q) return;
    abort.current?.abort();
    const ctrl = new AbortController();
    abort.current = ctrl;
    onChange(null);
    setShowLoose(false);
    setState({ status: "loading" });
    try {
      const items = await resolve(q, kind, ctrl.signal);
      if (ctrl.signal.aborted) return;
      setState({ status: "results", query: q, items });
      // One close match: pre-select it, still shown so the user can see what was picked.
      const { close } = splitMatches(q, items, kind === "investor");
      if (close.length === 1) onChange(close[0]);
    } catch (err) {
      if (ctrl.signal.aborted) return;
      setState({
        status: "error",
        message: describeError(err).message,
      });
    }
  }

  if (value) {
    return (
      <div>
        <p className="label">{label}</p>
        <div className="mt-3 flex items-start justify-between gap-3 border-l-2 border-accent bg-surface py-3 pr-3 pl-4">
          <EntityLine entity={value} />
          <button
            type="button"
            onClick={() => onChange(null)}
            className="shrink-0 text-sm underline underline-offset-4"
          >
            Change
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          void search(name);
        }}
      >
        <label htmlFor={id} className="label">
          {label}
        </label>
        <div className="mt-3 flex gap-2">
          <input
            id={id}
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder={placeholder}
            autoComplete="off"
            className="h-11 min-w-0 flex-1 rounded-[5px] border border-line bg-background px-3 text-base outline-none placeholder:text-muted focus:border-foreground"
          />
          <button
            type="submit"
            disabled={!name.trim() || state.status === "loading"}
            className="btn-ghost h-11 shrink-0"
          >
            {state.status === "loading" ? "Searching…" : "Find"}
          </button>
        </div>
      </form>

      {examples.length > 0 && state.status === "idle" && (
        <p className="mt-2 text-sm text-muted">
          Try{" "}
          {examples.map((ex, i) => (
            <span key={ex}>
              {i > 0 && ", "}
              <button
                type="button"
                className="text-foreground underline underline-offset-4"
                onClick={() => {
                  setName(ex);
                  void search(ex);
                }}
              >
                {ex}
              </button>
            </span>
          ))}
        </p>
      )}

      <div aria-live="polite">
        {state.status === "loading" && (
          <>
            <p className="mt-3 text-sm text-muted">Searching Cala…</p>
            <SlowNotice />
          </>
        )}
        {state.status === "error" && (
          <p className="mt-3 border-l-2 border-foreground pl-3 text-sm">
            {state.message}{" "}
            <button type="button" className="underline" onClick={() => void search(name)}>
              Try again
            </button>
          </p>
        )}
        {state.status === "results" && (
          <Results
            query={state.query}
            items={state.items}
            kind={kind}
            showLoose={showLoose}
            onShowLoose={() => setShowLoose(true)}
            onPick={onChange}
          />
        )}
      </div>
    </div>
  );
}

function Results({
  query,
  items,
  kind,
  showLoose,
  onShowLoose,
  onPick,
}: {
  query: string;
  items: EntityRef[];
  kind: EntityKind;
  showLoose: boolean;
  onShowLoose: () => void;
  onPick: (e: EntityRef) => void;
}) {
  const noun = kind === "investor" ? "investor" : "company";
  const { close, loose } = splitMatches(query, items, kind === "investor");
  const shown = showLoose ? [...close, ...loose] : close;
  return (
    <div className="mt-3">
      {close.length === 0 ? (
        <p className="text-sm text-muted">
          No {noun} named “{query}” in Cala. Check the spelling or try the full name
          {kind === "company" ? " (e.g. with “Oy” or “AB”)" : ""}.
        </p>
      ) : (
        <p className="text-sm text-muted">
          {close.length === 1 ? "1 match" : `${close.length} matches`} for “{query}”. Which one do you
          mean?
        </p>
      )}
      {shown.length > 0 && (
        <ul className="mt-3 divide-y divide-line border-y border-line">
          {shown.map((e) => (
            <li key={e.id}>
              <button
                type="button"
                onClick={() => onPick(e)}
                className="w-full px-1 py-3 text-left hover:bg-surface focus-visible:bg-surface"
              >
                <EntityLine entity={e} />
              </button>
            </li>
          ))}
        </ul>
      )}
      {!showLoose && loose.length > 0 && (
        <button type="button" onClick={onShowLoose} className="mt-2 text-sm text-muted underline underline-offset-4">
          Show {loose.length} looser {loose.length === 1 ? "match" : "matches"}
          {kind === "investor" ? " (similar names, or not an investor)" : " (names that only share a common word)"}
        </button>
      )}
    </div>
  );
}

function EntityLine({ entity }: { entity: EntityRef }) {
  return (
    <div className="min-w-0">
      <p className="flex flex-wrap items-center gap-2">
        <span className="font-medium">{entity.name}</span>
        <span className="label text-muted">{entity.type}</span>
      </p>
      <p className="mt-0.5 line-clamp-2 text-sm text-muted">
        {/* "" = description not passed along (e.g. preselected from a link), so say nothing. */}
        {entity.description === "" ? null : (entity.description ?? "No description in Cala.")}
      </p>
    </div>
  );
}

