  padding-block: 72px;
}
@media (min-width: 1024px) {
  .screen {
    min-height: 100svh;
    padding-block: 120px 96px;
  }
  .hero-screen {
    min-height: calc(100svh - 4rem); /* below the 64px header */
    padding-top: 96px;
  }
}

/* Edge to edge, content still on the page's left and right lines. */
.dark-band {
  margin-inline: calc(50% - 50vw);
  padding-inline: calc(50vw - 50%);
}

/* The hero enters once on load. */
@keyframes enter {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
.enter {
  animation: enter 0.7s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}
.enter-late {
  animation-delay: 0.15s;
}

/* Hover: cards lift 2px, buttons step and press, underlines draw. */
.lift {
  transition: transform 0.2s ease;
}
.lift:hover {
  transform: translateY(-2px);
}
.press {
  transition: transform 0.15s ease;
}
.press:hover {
  transform: translateY(-1px);
}
.press:active {
  transform: translateY(1px);
}
.draw {
  background: linear-gradient(currentColor, currentColor) left bottom / 100% 1px no-repeat;
  padding-bottom: 2px;
  transition: background-size 0.25s ease;
}
.draw:hover {
  background-size: 0% 1px;
  background-position: right bottom;
}

@media (prefers-reduced-motion: reduce) {
  .enter,
  .lift,
  .press,
  .draw {
    animation: none;
    transition: none;
  }
  .lift:hover,
  .press:hover,
  .press:active {
    transform: none;
  }
}
