"use client";

// Home: "I'm raising / I'm investing" toggle, then pick the entities and go.

import { useRouter } from "next/navigation";
import { useState } from "react";

import { EntityPicker } from "@/components/EntityPicker";
import { formatEuro, parseEuro } from "@/lib/money";
import { checkPath, founderPath } from "@/lib/routes";
import type { EntityRef } from "@/lib/types";

type Mode = "founder" | "investor";

const MODES: { value: Mode; label: string; hint: string }[] = [
  { value: "founder", label: "I'm raising", hint: "Who should I pitch, and who should I skip?" },
  {
    value: "investor",
    label: "I'm investing",
    hint: "Does this startup conflict with my portfolio, and who backed its rivals?",
  },
];

export function HomeForm() {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>("founder");
  const [company, setCompany] = useState<EntityRef | null>(null);
  const [fund, setFund] = useState<EntityRef | null>(null);
  const [startup, setStartup] = useState<EntityRef | null>(null);
  // Optional amount (C18): the raise (founder) or the most the fund puts in (investor).
  const [amountText, setAmountText] = useState({ founder: "", investor: "" });
  const text = amountText[mode];
  const amount = parseEuro(text);
  const amountInvalid = text.trim() !== "" && amount === null;

  const ready = (mode === "founder" ? company !== null : fund !== null && startup !== null) && !amountInvalid;

  function go() {
    if (mode === "founder" && company) router.push(founderPath(company.id, amount));
    if (mode === "investor" && fund && startup) router.push(checkPath(fund.id, startup.id, amount));
  }

  return (
    <div className="mt-14 max-w-xl">
      <div role="radiogroup" aria-label="Mode" className="flex gap-8 border-b border-line">
        {MODES.map((m) => (
          <button
            key={m.value}
            type="button"
            role="radio"
            aria-checked={mode === m.value}
            onClick={() => setMode(m.value)}
            className={`label -mb-px border-b-2 pb-3 transition-colors ${
              mode === m.value
                ? "border-accent text-foreground"
                : "border-transparent text-muted hover:text-foreground"
            }`}
          >
            {m.label}
          </button>
        ))}
      </div>
      <p className="mt-4 text-muted">{MODES.find((m) => m.value === mode)?.hint}</p>

      <div className="mt-10 space-y-8">
        {mode === "founder" ? (
          <EntityPicker
            key="company"
            kind="company"
            label="Your company"
            placeholder="e.g. Sensofusion"
            value={company}
            onChange={setCompany}
            examples={["Sensofusion", "Kelluu", "Stendr"]}
          />
        ) : (
          <>
            <EntityPicker
              key="fund"
              kind="investor"
              label="Your fund"
              placeholder="e.g. Tesi"
              value={fund}
              onChange={setFund}
              examples={["Tesi", "Maki.vc"]}
            />
            <EntityPicker
              key="startup"
              kind="company"
              label="The startup that pitched you"
              placeholder="e.g. NestAI"
              value={startup}
              onChange={setStartup}
              examples={["NestAI", "Stendr"]}
            />
          </>
        )}
        <div>
          <label htmlFor="home-amount" className="label">
            {mode === "founder" ? "Amount you want to raise" : "Most you will fund"}{" "}
            <span className="text-muted normal-case">(optional, EUR)</span>
          </label>
          <input
            id="home-amount"
            value={text}
            onChange={(e) => setAmountText((t) => ({ ...t, [mode]: e.target.value }))}
            placeholder={mode === "founder" ? "e.g. 3M" : "e.g. 500k"}
            inputMode="decimal"
            autoComplete="off"
            aria-invalid={amountInvalid}
            aria-describedby="home-amount-hint"
            className="mt-3 block h-11 w-48 rounded-[5px] border border-line bg-background px-3 text-base outline-none placeholder:text-muted focus:border-foreground aria-[invalid=true]:border-foreground"
          />
          <p id="home-amount-hint" className="mt-2 text-sm text-muted" aria-live="polite">
            {amountInvalid
              ? "Type an amount like 3M, 500k or 3 000 000."
              : amount !== null
                ? `${formatEuro(amount)}: compared with the round sizes in Cala.`
                : mode === "founder"
                  ? "Shows which investors join rounds of your size."
                  : "Shows whether this startup raises rounds your check fits."}
          </p>
        </div>
      </div>

      <button
        type="button"
        onClick={go}
        disabled={!ready}
        className="btn-primary mt-10"
      >
        {mode === "founder" ? "Find who to pitch" : "Check this startup"}
      </button>
    </div>
  );
}
"use client";

// Name → /api/resolve → the user confirms which Cala entity they mean
// (Cala has 5 "Inventure"s, so a match is never taken on name alone).

import { useEffect, useId, useRef, useState } from "react";

import { SlowNotice } from "@/components/SlowNotice";
import { describeError } from "@/lib/errors";
import { resolve } from "@/lib/api";
import { splitMatches } from "@/lib/match";
import type { EntityKind, EntityRef } from "@/lib/types";

type State =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "results"; query: string; items: EntityRef[] };

export interface EntityPickerProps {
  kind: EntityKind;
  label: string;
  placeholder: string;
  value: EntityRef | null;
  onChange: (entity: EntityRef | null) => void;
  examples?: string[];
}

export function EntityPicker({ kind, label, placeholder, value, onChange, examples = [] }: EntityPickerProps) {
  const id = useId();
  const [name, setName] = useState("");
  const [state, setState] = useState<State>({ status: "idle" });
  const [showLoose, setShowLoose] = useState(false);
  const abort = useRef<AbortController | null>(null);

  useEffect(() => () => abort.current?.abort(), []);

  async function search(query: string) {
    const q = query.trim();
    if (!q) return;
    abort.current?.abort();
    const ctrl = new AbortController();
    abort.current = ctrl;
    onChange(null);
    setShowLoose(false);
    setState({ status: "loading" });
    try {
      const items = await resolve(q, kind, ctrl.signal);
      if (ctrl.signal.aborted) return;
      setState({ status: "results", query: q, items });
      // One close match: pre-select it, still shown so the user can see what was picked.
      const { close } = splitMatches(q, items, kind === "investor");
      if (close.length === 1) onChange(close[0]);
    } catch (err) {
      if (ctrl.signal.aborted) return;
      setState({
        status: "error",
        message: describeError(err).message,
      });
    }
  }

  if (value) {
    return (
      <div>
        <p className="label">{label}</p>
        <div className="mt-3 flex items-start justify-between gap-3 border-l-2 border-accent bg-surface py-3 pr-3 pl-4">
          <EntityLine entity={value} />
          <button
            type="button"
            onClick={() => onChange(null)}
            className="shrink-0 text-sm underline underline-offset-4"
          >
            Change
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          void search(name);
        }}
      >
        <label htmlFor={id} className="label">
          {label}
        </label>
        <div className="mt-3 flex gap-2">
          <input
            id={id}
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder={placeholder}
            autoComplete="off"
            className="h-11 min-w-0 flex-1 rounded-[5px] border border-line bg-background px-3 text-base outline-none placeholder:text-muted focus:border-foreground"
          />
          <button
            type="submit"
            disabled={!name.trim() || state.status === "loading"}
            className="btn-ghost h-11 shrink-0"
          >
            {state.status === "loading" ? "Searching…" : "Find"}
          </button>
        </div>
      </form>

      {examples.length > 0 && state.status === "idle" && (
        <p className="mt-2 text-sm text-muted">
          Try{" "}
          {examples.map((ex, i) => (
            <span key={ex}>
              {i > 0 && ", "}
              <button
                type="button"
                className="text-foreground underline underline-offset-4"
                onClick={() => {
                  setName(ex);
                  void search(ex);
                }}
              >
                {ex}
              </button>
            </span>
          ))}
        </p>
      )}

      <div aria-live="polite">
        {state.status === "loading" && (
          <>
            <p className="mt-3 text-sm text-muted">Searching Cala…</p>
            <SlowNotice />
          </>
        )}
        {state.status === "error" && (
          <p className="mt-3 border-l-2 border-foreground pl-3 text-sm">
            {state.message}{" "}
            <button type="button" className="underline" onClick={() => void search(name)}>
              Try again
            </button>
          </p>
        )}
        {state.status === "results" && (
          <Results
            query={state.query}
            items={state.items}
            kind={kind}
            showLoose={showLoose}
            onShowLoose={() => setShowLoose(true)}
            onPick={onChange}
          />
        )}
      </div>
    </div>
  );
}

function Results({
  query,
  items,
  kind,
  showLoose,
  onShowLoose,
  onPick,
}: {
  query: string;
  items: EntityRef[];
  kind: EntityKind;
  showLoose: boolean;
  onShowLoose: () => void;
  onPick: (e: EntityRef) => void;
}) {
  const noun = kind === "investor" ? "investor" : "company";
  const { close, loose } = splitMatches(query, items, kind === "investor");
  const shown = showLoose ? [...close, ...loose] : close;
  return (
    <div className="mt-3">
      {close.length === 0 ? (
        <p className="text-sm text-muted">
          No {noun} named “{query}” in Cala. Check the spelling or try the full name
          {kind === "company" ? " (e.g. with “Oy” or “AB”)" : ""}.
        </p>
      ) : (
        <p className="text-sm text-muted">
          {close.length === 1 ? "1 match" : `${close.length} matches`} for “{query}”. Which one do you
          mean?
        </p>
      )}
      {shown.length > 0 && (
        <ul className="mt-3 divide-y divide-line border-y border-line">
          {shown.map((e) => (
            <li key={e.id}>
              <button
                type="button"
                onClick={() => onPick(e)}
                className="w-full px-1 py-3 text-left hover:bg-surface focus-visible:bg-surface"
              >
                <EntityLine entity={e} />
              </button>
            </li>
          ))}
        </ul>
      )}
      {!showLoose && loose.length > 0 && (
        <button type="button" onClick={onShowLoose} className="mt-2 text-sm text-muted underline underline-offset-4">
          Show {loose.length} looser {loose.length === 1 ? "match" : "matches"}
          {kind === "investor" ? " (similar names, or not an investor)" : " (names that only share a common word)"}
        </button>
      )}
    </div>
  );
}

function EntityLine({ entity }: { entity: EntityRef }) {
  return (
    <div className="min-w-0">
      <p className="flex flex-wrap items-center gap-2">
        <span className="font-medium">{entity.name}</span>
        <span className="label text-muted">{entity.type}</span>
      </p>
      <p className="mt-0.5 line-clamp-2 text-sm text-muted">
        {/* "" = description not passed along (e.g. preselected from a link), so say nothing. */}
        {entity.description === "" ? null : (entity.description ?? "No description in Cala.")}
      </p>
    </div>
  );
}

"use client";

// Founder report (C5, C6): company header, competitor chips, then the Pitch and
// Skip lists. Removing competitors and pressing "Re-rank" calls
// /api/founder/analyze again with the remaining `competitor_ids`.

import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";

import { ChatPanel } from "@/components/ChatPanel";
import { CompetitorChips } from "@/components/CompetitorChips";
import { AmountField } from "@/components/FundingFit";
import { PitchCard, SkipCard } from "@/components/InvestorCard";
import { SlowNotice } from "@/components/SlowNotice";
import { SourceBadges } from "@/components/SourceBadge";
import { analyzeFounder } from "@/lib/api";
import { describeError } from "@/lib/errors";
import { keptCompetitorIds, prettyEnum } from "@/lib/format";
import { prepPath } from "@/lib/routes";
import type { Company, FounderReport } from "@/lib/types";

// Live reports rank 30-45 investors; the top ones matter, and the Skip list below
// (the conflict) must stay within reach: each card is ~235 px tall.
const PITCH_SHOWN = 5;

type Load =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean; detail: string | null }
  | { status: "ready"; report: FounderReport; reranking: boolean; rerankError: string | null };

export function FounderReportView({
  companyId,
  initialTarget = null,
}: {
  companyId: string;
  initialTarget?: number | null; // ?raise= in the URL (C18)
}) {
  const [load, setLoad] = useState<Load>({ status: "loading" });
  const [removed, setRemoved] = useState<Set<string>>(new Set());
  const [narrowed, setNarrowed] = useState(false); // ranked against a user-edited list
  const [showAllPitch, setShowAllPitch] = useState(false);
  const [target, setTarget] = useState<number | null>(initialTarget); // the founder's raise (B21)
  const abort = useRef<AbortController | null>(null);

  // Fetches and stores a report. State is set only in the promise callbacks, so the initial
  // load can run from an effect; `run` below flips the loading state first, from handlers.
  const fetchReport = useCallback(
    (competitorIds?: string[], raise?: number | null) => {
      abort.current?.abort();
      const ctrl = new AbortController();
      abort.current = ctrl;
      return analyzeFounder(
        {
          company_id: companyId,
          ...(competitorIds ? { competitor_ids: competitorIds } : {}),
          ...(raise ? { target_amount_eur: raise } : {}),
        },
        ctrl.signal,
      ).then(
        (report) => {
          if (ctrl.signal.aborted) return;
          setLoad({ status: "ready", report, reranking: false, rerankError: null });
          setRemoved(new Set());
          setNarrowed(Boolean(competitorIds));
          setShowAllPitch(false);
        },
        (err: unknown) => {
          if (ctrl.signal.aborted) return;
          const e = describeError(err);
          setLoad((prev) =>
            prev.status === "ready" && competitorIds
              ? { ...prev, reranking: false, rerankError: e.message }
              : { status: "error", message: e.message, notFound: e.notFound, detail: e.detail },
          );
        },
      );
    },
    [companyId],
  );

  function run(competitorIds?: string[], raise: number | null = target, keepReport = false) {
    setLoad((prev) =>
      prev.status === "ready" && (competitorIds || keepReport)
        ? { ...prev, reranking: true, rerankError: null }
        : { status: "loading" },
    );
    void fetchReport(competitorIds, raise);
  }

  // A new raise re-ranks against the same competitors, and is kept in the URL (?raise=).
  function applyRaise(raise: number | null) {
    setTarget(raise);
    const url = new URL(window.location.href);
    if (raise) url.searchParams.set("raise", String(raise));
    else url.searchParams.delete("raise");
    window.history.replaceState(null, "", url);
    const current =
      load.status === "ready" && narrowed ? load.report.competitors.map((c) => c.company.id) : undefined;
    run(current, raise, true);
  }

  useEffect(() => {
    void fetchReport(undefined, initialTarget);
    return () => abort.current?.abort();
  }, [fetchReport, initialTarget]);

  if (load.status === "loading") return <LoadingReport />;
  if (load.status === "error") {
    return (
      <div className="max-w-xl">
        <p className="label text-muted">Founder report</p>
        <h1 className="display mt-4 text-5xl">
          {load.notFound ? "We couldn't find that company." : "The report didn't load."}
        </h1>
        <p className="mt-6 border-l-2 border-foreground pl-3">{load.message}</p>
        {load.detail && (
          <details className="mt-3 text-sm text-muted">
            <summary className="cursor-pointer">Technical details</summary>
            <p className="mt-2 font-mono text-xs break-all">{load.detail}</p>
          </details>
        )}
        <div className="mt-8 flex gap-3">
          {!load.notFound && (
            <button type="button" className="btn-primary" onClick={() => void run()}>
              Try again
            </button>
          )}
          <Link href="/" className="btn-ghost h-[47px]">
            Search again
          </Link>
        </div>
      </div>
    );
  }

  const { report, reranking, rerankError } = load;
  const ids = report.competitors.map((c) => c.company.id);
  const kept = keptCompetitorIds(ids, removed);

  return (
    <div>
      <title>{`${report.company.name} · Founder report · PitchSwitch`}</title>
      <ChatPanel
        companyId={report.company.id}
        scope={report.company.name}
        suggestions={[
          "Who are my top 3 investors to pitch, and why?",
          ...(report.skip[0] ? [`Why should I skip ${report.skip[0].investor.name}?`] : []),
          ...(report.pitch[0] ? [`What has ${report.pitch[0].investor.name} led recently?`] : []),
        ]}
      />
      <CompanyHeader company={report.company} />

      <section className="mt-16 border-t border-line pt-8">
        <div className="flex flex-wrap items-baseline justify-between gap-4">
          <div>
            <p className="label">Competitors · {kept.length}</p>
            <p className="mt-2 max-w-xl text-sm text-muted">
              Investors who backed these go on the Skip list. Hover a name to see why it counts;
              remove the ones that don&apos;t, then re-rank.
            </p>
          </div>
          <div className="flex items-center gap-4">
            {narrowed && removed.size === 0 && (
              <button
                type="button"
                disabled={reranking}
                onClick={() => void run()}
                className="text-sm underline underline-offset-4 disabled:opacity-40"
              >
                Reset to all competitors
              </button>
            )}
            {removed.size > 0 && (
              <button
                type="button"
                disabled={reranking}
                onClick={() => void run(kept)}
                className="btn-primary"
              >
                {reranking ? "Re-ranking…" : `Re-rank with ${kept.length}`}
              </button>
            )}
          </div>
        </div>
        {reranking && <SlowNotice />}
        {rerankError && (
          <p className="mt-4 border-l-2 border-foreground pl-3 text-sm">
            Re-ranking failed: {rerankError}
          </p>
        )}
        <div className="mt-6">
          {report.competitors.length === 0 ? (
            <p className="text-muted">
              No direct competitors found in Cala, so no investor has a conflict yet.
            </p>
          ) : (
            <CompetitorChips
              competitors={report.competitors}
              removed={removed}
              disabled={reranking}
              onRemove={(id) => setRemoved((s) => new Set(s).add(id))}
              onRestore={(id) =>
                setRemoved((s) => {
                  const next = new Set(s);
                  next.delete(id);
                  return next;
                })
              }
            />
          )}
        </div>
      </section>

      <section className="mt-12 border-t border-line pt-8" aria-label="Funding amount">
        <AmountField side="founder" value={target} onApply={applyRaise} disabled={reranking} />
