            </p>
          ) : (
            <ul className="mt-6">
              {report.skip.map((s) => (
                <li key={s.investor.id}>
                  <SkipCard item={s} companyId={report.company.id} companyName={report.company.name} />
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>
    </div>
  );
}

