617	          <li key={`${p.text}-${i}`} className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
618	            <span className="border-b-2 border-accent">{p.text}</span>
619	            {/* co_investors() has no sources yet (notes/B.md): say where it comes from instead of "No source". */}
620	            {p.sources.length > 0 ? (
621	              <SourceBadges sources={p.sources} />
622	            ) : (
623	              <span className="text-xs text-muted">from co-investment data</span>
624	            )}
625	          </li>
626	        ))}
627	      </ul>
628	    </div>
629	  );
630	}
631	"use client";
632	
633	// Competitor chips (C5): one chip per competitor, the reason in a tooltip
634	// (hover, keyboard focus or tap), and a × to remove a wrong match.
635	
636	import { useState } from "react";
637	
638	import { SourceBadges } from "@/components/SourceBadge";
639	import type { Competitor } from "@/lib/types";
640	
641	export function CompetitorChips({
642	  competitors,
643	  removed,
644	  onRemove,
645	  onRestore,
646	  disabled = false,
647	}: {
648	  competitors: Competitor[];
649	  removed: ReadonlySet<string>;
650	  onRemove: (id: string) => void;
651	  onRestore: (id: string) => void;
652	  disabled?: boolean;
653	}) {
654	  const kept = competitors.filter((c) => !removed.has(c.company.id));
655	  const gone = competitors.filter((c) => removed.has(c.company.id));
656	
657	  return (
658	    <div>
659	      <ul className="relative flex flex-wrap gap-2">
660	        {kept.map((c) => (
661	          <Chip key={c.company.id} competitor={c} onRemove={onRemove} disabled={disabled} />
662	        ))}
663	      </ul>
664	      {gone.length > 0 && (
665	        <p className="mt-4 text-sm text-muted">
666	          <span className="label mr-2">Removed</span>
667	          {gone.map((c, i) => (
668	            <span key={c.company.id}>
669	              {i > 0 && ", "}
670	              <s>{c.company.name}</s>{" "}
671	              <button
672	                type="button"
673	                disabled={disabled}
674	                onClick={() => onRestore(c.company.id)}
675	                className="text-foreground underline underline-offset-4 disabled:opacity-40"
676	              >
677	                restore
678	              </button>
679	            </span>
680	          ))}
681	        </p>
682	      )}
683	    </div>
684	  );
685	}
686	
687	function Chip({
688	  competitor,
689	  onRemove,
690	  disabled,
691	}: {
692	  competitor: Competitor;
693	  onRemove: (id: string) => void;
694	  disabled: boolean;
695	}) {
696	  const [open, setOpen] = useState(false);
697	  const { company, reason } = competitor;
698	  const tipId = `tip-${company.id}`;
699	  const meta = [company.stage, company.country].filter(Boolean).join(" · ");
700	
701	  return (
702	    <li
703	      className="group md:relative"
704	      onMouseLeave={() => setOpen(false)}
705	      onKeyDown={(e) => e.key === "Escape" && setOpen(false)}
706	    >
707	      <span className="inline-flex items-center rounded-[5px] border border-foreground bg-background">
708	        <button
709	          type="button"
710	          aria-describedby={tipId}
711	          aria-expanded={open}
712	          onClick={() => setOpen((o) => !o)}
713	          className="py-1.5 pr-1 pl-3 text-sm font-medium"
714	        >
715	          {company.name}
716	        </button>
717	        <button
718	          type="button"
719	          disabled={disabled}
720	          onClick={() => onRemove(company.id)}
721	          aria-label={`Remove ${company.name} — not a real competitor`}
722	          title="Not a competitor? Remove it"
723	          className="px-2 py-1.5 text-muted hover:text-foreground disabled:opacity-40"
724	        >
725	          ×
726	        </button>
727	      </span>
728	      <div
729	        id={tipId}
730	        role="tooltip"
731	        className={`absolute top-full right-0 left-0 z-20 mt-2 border md:right-auto md:w-72 border-foreground bg-background p-4 text-left ${
732	          open ? "block" : "hidden group-focus-within:block group-hover:block"
733	        }`}
734	      >
735	        {meta && <p className="label text-muted">{meta}</p>}
736	        <p className="mt-2 text-sm leading-snug">{reason}</p>
737	        <p className="label mt-3 text-muted">Why a competitor: AI judgement</p>
738	        {company.description && (
739	          <p className="mt-3 line-clamp-4 border-t border-line pt-3 text-sm leading-snug text-muted">
740	            {company.description}
741	          </p>
742	        )}
743	        <div className="mt-3">
744	          <SourceBadges sources={company.sources} />
745	        </div>
746	      </div>
747	    </li>
748	  );
749	}
750	// Source badge: rank + date + link, shown next to every claim (CLAUDE.md §6, C4).
751	// No client JS: <details> handles "+N more", so it works in server components too.
752	
753	import { formatSourceDate, rankLabel, safeUrl, sortSources } from "@/lib/sources";
754	import type { Source, SourceRank } from "@/lib/types";
755	
756	// DESIGN.md allows one accent, so reliability is shown by weight, not hue:
757	// green tints for first-hand sources, ink outline for press, faint for the rest.
758	const RANK_STYLE: Record<SourceRank, string> = {
759	  PRIMARY: "border-moss bg-echo text-foreground",
760	  FILING: "border-moss bg-surface text-foreground",
761	  PRESS: "border-foreground/40 bg-background text-foreground",
762	  AGGREGATOR: "border-line bg-background text-muted",
763	  UNKNOWN: "border-dashed border-line bg-background text-muted",
764	};
765	
766	const BASE =
767	  "inline-flex max-w-full items-center gap-1.5 rounded-[5px] border px-1.5 py-0.5 text-xs leading-4 whitespace-nowrap";
768	
769	export function SourceBadge({ source }: { source: Source }) {
770	  const date = formatSourceDate(source.date);
771	  const href = safeUrl(source.url);
772	  const title = [source.name, source.date, source.url].filter(Boolean).join(" · ");
773	  const body = (
774	    <>
775	      <span className="label">{rankLabel(source.rank)}</span>
776	      {date && <span className="opacity-75">{date}</span>}
777	      {href && <span aria-hidden="true">↗</span>}
778	    </>
779	  );
780	
781	  if (!href) {
782	    return (
783	      <span className={`${BASE} ${RANK_STYLE[source.rank]}`} title={title}>
784	        {body}
785	      </span>
786	    );
787	  }
788	  return (
789	    <a
790	      href={href}
791	      target="_blank"
792	      rel="noopener noreferrer"
793	      title={title}
794	      aria-label={`${rankLabel(source.rank)} source: ${source.name}${date ? `, ${date}` : ""} (opens in a new tab)`}
795	      className={`${BASE} ${RANK_STYLE[source.rank]} hover:border-foreground`}
796	    >
797	      {body}
798	    </a>
799	  );
800	}
801	
802	/**
803	 * All sources of one claim: the most reliable first, the rest behind "+N".
804	 * Renders "No source" when the list is empty, so a missing source is visible.
805	 */
806	export function SourceBadges({ sources, max = 1 }: { sources: Source[]; max?: number }) {
807	  if (sources.length === 0) {
808	    return <span className={`${BASE} ${RANK_STYLE.UNKNOWN} italic`}>No source</span>;
809	  }
810	  const sorted = sortSources(sources);
811	  const shown = sorted.slice(0, max);
812	  const rest = sorted.slice(max);
813	  return (
814	    <span className="inline-flex flex-wrap items-center gap-1 align-middle">
815	      {shown.map((s, i) => (
816	        <SourceBadge key={`${s.url ?? s.name}-${i}`} source={s} />
817	      ))}
818	      {rest.length > 0 && (
819	        <details className="group inline-block">
820	          <summary
821	            className={`${BASE} ${RANK_STYLE.UNKNOWN} cursor-pointer list-none hover:text-foreground [&::-webkit-details-marker]:hidden`}
822	          >
823	            <span className="group-open:hidden">+{rest.length}</span>
824	            <span className="hidden group-open:inline">less</span>
825	          </summary>
826	          <span className="mt-1 flex flex-wrap gap-1">
827	            {rest.map((s, i) => (
828	              <SourceBadge key={`${s.url ?? s.name}-${i}`} source={s} />
829	            ))}
830	          </span>
831	        </details>
832	      )}
833	    </span>
834	  );
835	}
836	"use client";
837	
838	// Funding amount (C18, B21): the optional amount field and the fit line on cards and checks.
839	// Founder side: "how much you want to raise"; investor side: "the most you will fund".
840	
841	import { useState } from "react";
842	
843	import { SourceBadges } from "@/components/SourceBadge";
844	import { formatEuro, parseEuro } from "@/lib/money";
845	import type { FundingFit, FundingVerdict } from "@/lib/types";
846	
847	export type FundingSide = "founder" | "investor";
848	
849	const LABEL: Record<FundingSide, Record<FundingVerdict, string>> = {
850	  founder: {
851	    fits: "Fits your raise",
852	    too_small: "Raise below their range",
853	    too_large: "Raise above their range",
854	    unknown: "Round sizes unknown",
855	  },
856	  investor: {
857	    fits: "Fits your check",
858	    too_small: "Raises less than your check",
859	    too_large: "Your check is a small share",
860	    unknown: "Round sizes unknown",
861	  },
862	};
863	
864	// One accent (DESIGN.md): a fit is green, a mismatch is ink, unknown is faint.
865	const STYLE: Record<FundingVerdict, string> = {
866	  fits: "bg-echo border-moss text-foreground",
867	  too_small: "bg-background border-foreground text-foreground",
868	  too_large: "bg-background border-foreground text-foreground",
869	  unknown: "bg-background border-dashed border-line text-muted",
870	};
871	
872	export function FundingFitLine({ fit, side }: { fit: FundingFit; side: FundingSide }) {
873	  return (
874	    <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
875	      <span className={`label rounded-[5px] border px-1.5 py-1 ${STYLE[fit.verdict]}`}>{LABEL[side][fit.verdict]}</span>
876	      <span className={fit.verdict === "unknown" ? "text-muted" : ""}>{fit.text}</span>
877	      {fit.sources.length > 0 && <SourceBadges sources={fit.sources} />}
878	    </div>
879	  );
880	}
881	
882	/**
883	 * The optional amount: type "3M", "€500k" or "3 000 000". `onApply(null)` clears it.
884	 * Shows what will be sent (€3M) before it's applied, and an error for anything that isn't an amount.
885	 */
886	export function AmountField({
887	  side,
888	  value,
889	  onApply,
890	  disabled = false,
891	}: {
892	  side: FundingSide;
893	  value: number | null;
894	  onApply: (amount: number | null) => void;
895	  disabled?: boolean;
896	}) {
897	  const [text, setText] = useState(value ? formatEuro(value) : "");
898	  const parsed = parseEuro(text);
899	  const invalid = text.trim() !== "" && parsed === null;
900	  const label = side === "founder" ? "Amount you want to raise" : "Most you will fund";
901	  const id = `amount-${side}`;
902	  const changed = (parsed ?? null) !== value;
903	
904	  return (
905	    <form
906	      onSubmit={(e) => {
907	        e.preventDefault();
908	        if (!invalid && changed) onApply(parsed);
909	      }}
910	    >
911	      <label htmlFor={id} className="label">
912	        {label} <span className="text-muted normal-case">(optional, EUR)</span>
913	      </label>
914	      <div className="mt-2 flex items-center gap-2">
915	        <input
916	          id={id}
917	          value={text}
918	          onChange={(e) => setText(e.target.value)}
919	          placeholder={side === "founder" ? "e.g. 3M" : "e.g. 500k"}
920	          inputMode="decimal"
921	          autoComplete="off"
922	          aria-invalid={invalid}
923	          aria-describedby={`${id}-hint`}
924	          disabled={disabled}
925	          className="block h-10 w-44 rounded-[5px] border border-line bg-background px-3 outline-none placeholder:text-muted focus:border-foreground aria-[invalid=true]:border-foreground disabled:opacity-50"
926	        />
927	        <button type="submit" className="btn-ghost h-10" disabled={disabled || invalid || !changed}>
928	          {parsed === null && value !== null ? "Clear" : "Apply"}
929	        </button>
930	      </div>
931	      <p id={`${id}-hint`} className="mt-2 text-xs text-muted" aria-live="polite">
932	        {invalid
933	          ? "Type an amount like 3M, 500k or 3 000 000."
934	          : parsed !== null && changed
935	            ? `Compares ${formatEuro(parsed)} with the round sizes in Cala.`
936	            : side === "founder"
937	              ? "Compared with the sizes of the rounds each investor joins (whole rounds, not their share)."
938	              : "Compared with the sizes of this startup's rounds (whole rounds, not one investor's share)."}
939	      </p>
940	    </form>
941	  );
942	}
943	"use client";
944	
945	// Shown under a loading state once it has taken a while. Uncached Cala queries
946	// take 20–80 s each (notes/A.md) and a cold founder report can need hundreds of
947	// them (notes/B.md), so a silent spinner would look broken.
948	
949	import { useEffect, useState } from "react";
950	
951	const STAGES: { after: number; text: string }[] = [
952	  { after: 8, text: "Still working. Cached companies load in seconds; a company we haven't seen before needs fresh Cala lookups." },
953	  { after: 45, text: "This company isn't cached yet, so every lookup goes to Cala. The first run can take several minutes; after that it's instant." },
954	  { after: 300, text: "Still going: this is a big one. Keep this tab open and it will appear when ready." },
955	];
956	
957	export function SlowNotice() {
958	  const [seconds, setSeconds] = useState(0);
959	  useEffect(() => {
960	    const t = setInterval(() => setSeconds((s) => s + 1), 1000);
961	    return () => clearInterval(t);
962	  }, []);
963	  const stage = [...STAGES].reverse().find((s) => seconds >= s.after);
964	  if (!stage) return null;
965	  return (
966	    <p className="mt-4 max-w-xl border-l-2 border-accent pl-3 text-sm" role="status">
967	      {stage.text} <span className="text-muted">({seconds} s)</span>
968	    </p>
969	  );
970	}
