}

function Name({ item }: { item: InvestorScore }) {
  return (
    <h3 className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
      <span className="text-xl font-medium tracking-tight">{item.investor.name}</span>
      <span className="label text-muted">{item.investor.type === "Person" ? "Angel" : item.investor.type}</span>
    </h3>
  );
}

function Signals({ item }: { item: InvestorScore }) {
  return (
    <p className="mt-2 text-sm text-muted">
      {leadSummary(item)}
      <span aria-hidden="true"> · </span>
      {activitySummary(item)}
    </p>
  );
}

function Score({ value }: { value: number }) {
  const v = Math.round(value);
  return (
    <div className="col-start-2 mt-4 md:col-start-auto md:mt-0 md:text-right">
      <p className="display text-4xl text-muted md:text-5xl">{v}</p>
      <p className="label mt-1 text-muted">Fit / 100</p>
      <div className="mt-2 h-1 w-24 bg-surface md:ml-auto" aria-hidden="true">
        <div className="h-1 bg-accent" style={{ width: `${Math.max(0, Math.min(100, v))}%` }} />
      </div>
    </div>
  );
}

/**
 * How the score adds up (C17): B's first reason as one bar per signal. Each bar's track is as
 * long as that signal's weight, so the 25-point signals look bigger than the 10-point ones.
 */
function Breakdown({ item, open = false, skip = false }: { item: InvestorScore; open?: boolean; skip?: boolean }) {
  const { breakdown, source } = splitReasons(item.reasons);
  if (!breakdown) return null;
  const title = skip
    ? `How the ${fmt(breakdown.total)} (fit despite the conflict) adds up`
    : `How the ${fmt(breakdown.total)} adds up`;
  return (
    <details className="group/b mt-4" open={open}>
      <summary className="label cursor-pointer list-none text-muted hover:text-foreground [&::-webkit-details-marker]:hidden">
        <span className="group-open/b:hidden">+ {title}</span>
        <span className="hidden group-open/b:inline">− {title}</span>
      </summary>
      <BreakdownRows breakdown={breakdown} sources={source?.sources ?? []} />
    </details>
  );
}

function BreakdownRows({ breakdown, sources }: { breakdown: ScoreBreakdown; sources: Source[] }) {
  const widest = Math.max(...breakdown.parts.map((p) => p.max), 1);
  return (
    <div className="mt-3">
      <table className="w-full max-w-2xl text-sm">
        <caption className="sr-only">Score breakdown, {fmt(breakdown.total)} out of {breakdown.outOf}</caption>
        <tbody>
          {breakdown.parts.map((p) => (
            <tr key={p.name} className="align-top">
              <th scope="row" className="w-36 py-1 pr-3 text-left font-normal first-letter:uppercase">
                {p.name}
              </th>
              <td className="w-40 py-1 pr-3">
                <div
                  className="mt-1.5 h-1.5 bg-surface"
                  style={{ width: `${(p.max / widest) * 100}%` }}
                  role="img"
                  aria-label={`${fmt(p.got)} of ${fmt(p.max)} points`}
                >
                  <div className="h-1.5 bg-accent" style={{ width: `${p.max ? Math.min(100, (p.got / p.max) * 100) : 0}%` }} />
                </div>
              </td>
              <td className="w-14 py-1 pr-3 text-right tabular-nums">
                {fmt(p.got)}/{fmt(p.max)}
              </td>
              <td className="py-1 text-muted">{p.detail}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {sources.length > 0 && (
        <div className="mt-2 flex flex-wrap items-center gap-2 text-xs text-muted">
          Rounds counted <SourceBadges sources={sources} />
        </div>
      )}
    </div>
  );
}

const fmt = (n: number) => (Number.isInteger(n) ? String(n) : n.toFixed(1));

function Reasons({ reasons, all = false }: { reasons: Reason[]; all?: boolean }) {
  if (reasons.length === 0) return null;
  const shown = all ? reasons : reasons.slice(0, VISIBLE_REASONS);
  const rest = all ? [] : reasons.slice(VISIBLE_REASONS);
  return (
    <div className="mt-4">
      <ReasonList reasons={shown} />
      {rest.length > 0 && (
        <details className="group mt-2">
          <summary className="label cursor-pointer list-none text-muted hover:text-foreground [&::-webkit-details-marker]:hidden">
            <span className="group-open:hidden">+ {rest.length} more</span>
            <span className="hidden group-open:inline">− Fewer</span>
          </summary>
          <ReasonList reasons={rest} />
        </details>
      )}
    </div>
  );
}

function ReasonList({ reasons }: { reasons: Reason[] }) {
  return (
    <ul className="space-y-1.5">
      {reasons.map((r, i) => (
        <li key={`${r.text}-${i}`} className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
          <span>{r.text}</span>
          <SourceBadges sources={r.sources} />
        </li>
      ))}
    </ul>
  );
}

function WarmPaths({ paths }: { paths: Reason[] }) {
  if (paths.length === 0) return null;
  return (
    <div className="mt-4">
      <p className="label">Warm path</p>
      <ul className="mt-1.5 space-y-1.5">
        {paths.map((p, i) => (
          <li key={`${p.text}-${i}`} className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
            <span className="border-b-2 border-accent">{p.text}</span>
            {/* co_investors() has no sources yet (notes/B.md): say where it comes from instead of "No source". */}
            {p.sources.length > 0 ? (
              <SourceBadges sources={p.sources} />
            ) : (
              <span className="text-xs text-muted">from co-investment data</span>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}
"use client";

// Competitor chips (C5): one chip per competitor, the reason in a tooltip
// (hover, keyboard focus or tap), and a × to remove a wrong match.

import { useState } from "react";

import { SourceBadges } from "@/components/SourceBadge";
import type { Competitor } from "@/lib/types";

export function CompetitorChips({
  competitors,
  removed,
  onRemove,
  onRestore,
  disabled = false,
}: {
  competitors: Competitor[];
  removed: ReadonlySet<string>;
  onRemove: (id: string) => void;
  onRestore: (id: string) => void;
  disabled?: boolean;
}) {
  const kept = competitors.filter((c) => !removed.has(c.company.id));
  const gone = competitors.filter((c) => removed.has(c.company.id));

  return (
    <div>
      <ul className="relative flex flex-wrap gap-2">
        {kept.map((c) => (
          <Chip key={c.company.id} competitor={c} onRemove={onRemove} disabled={disabled} />
        ))}
      </ul>
      {gone.length > 0 && (
        <p className="mt-4 text-sm text-muted">
          <span className="label mr-2">Removed</span>
          {gone.map((c, i) => (
            <span key={c.company.id}>
              {i > 0 && ", "}
              <s>{c.company.name}</s>{" "}
              <button
                type="button"
                disabled={disabled}
                onClick={() => onRestore(c.company.id)}
                className="text-foreground underline underline-offset-4 disabled:opacity-40"
              >
                restore
              </button>
            </span>
          ))}
        </p>
      )}
    </div>
  );
}

function Chip({
  competitor,
  onRemove,
  disabled,
}: {
  competitor: Competitor;
  onRemove: (id: string) => void;
  disabled: boolean;
}) {
  const [open, setOpen] = useState(false);
  const { company, reason } = competitor;
  const tipId = `tip-${company.id}`;
  const meta = [company.stage, company.country].filter(Boolean).join(" · ");

  return (
    <li
      className="group md:relative"
      onMouseLeave={() => setOpen(false)}
      onKeyDown={(e) => e.key === "Escape" && setOpen(false)}
    >
      <span className="inline-flex items-center rounded-[5px] border border-foreground bg-background">
        <button
          type="button"
          aria-describedby={tipId}
          aria-expanded={open}
          onClick={() => setOpen((o) => !o)}
          className="py-1.5 pr-1 pl-3 text-sm font-medium"
        >
          {company.name}
        </button>
        <button
          type="button"
          disabled={disabled}
          onClick={() => onRemove(company.id)}
          aria-label={`Remove ${company.name} — not a real competitor`}
          title="Not a competitor? Remove it"
          className="px-2 py-1.5 text-muted hover:text-foreground disabled:opacity-40"
        >
          ×
        </button>
      </span>
      <div
        id={tipId}
        role="tooltip"
        className={`absolute top-full right-0 left-0 z-20 mt-2 border md:right-auto md:w-72 border-foreground bg-background p-4 text-left ${
          open ? "block" : "hidden group-focus-within:block group-hover:block"
        }`}
      >
        {meta && <p className="label text-muted">{meta}</p>}
        <p className="mt-2 text-sm leading-snug">{reason}</p>
        <p className="label mt-3 text-muted">Why a competitor: AI judgement</p>
        {company.description && (
          <p className="mt-3 line-clamp-4 border-t border-line pt-3 text-sm leading-snug text-muted">
            {company.description}
          </p>
        )}
        <div className="mt-3">
          <SourceBadges sources={company.sources} />
        </div>
      </div>
    </li>
  );
}
// Source badge: rank + date + link, shown next to every claim (CLAUDE.md §6, C4).
// No client JS: <details> handles "+N more", so it works in server components too.

import { formatSourceDate, rankLabel, safeUrl, sortSources } from "@/lib/sources";
import type { Source, SourceRank } from "@/lib/types";

// DESIGN.md allows one accent, so reliability is shown by weight, not hue:
// green tints for first-hand sources, ink outline for press, faint for the rest.
const RANK_STYLE: Record<SourceRank, string> = {
  PRIMARY: "border-moss bg-echo text-foreground",
  FILING: "border-moss bg-surface text-foreground",
  PRESS: "border-foreground/40 bg-background text-foreground",
  AGGREGATOR: "border-line bg-background text-muted",
  UNKNOWN: "border-dashed border-line bg-background text-muted",
};

const BASE =
  "inline-flex max-w-full items-center gap-1.5 rounded-[5px] border px-1.5 py-0.5 text-xs leading-4 whitespace-nowrap";

export function SourceBadge({ source }: { source: Source }) {
  const date = formatSourceDate(source.date);
  const href = safeUrl(source.url);
  const title = [source.name, source.date, source.url].filter(Boolean).join(" · ");
  const body = (
    <>
      <span className="label">{rankLabel(source.rank)}</span>
      {date && <span className="opacity-75">{date}</span>}
      {href && <span aria-hidden="true">↗</span>}
    </>
  );

  if (!href) {
    return (
      <span className={`${BASE} ${RANK_STYLE[source.rank]}`} title={title}>
        {body}
      </span>
    );
  }
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      title={title}
      aria-label={`${rankLabel(source.rank)} source: ${source.name}${date ? `, ${date}` : ""} (opens in a new tab)`}
      className={`${BASE} ${RANK_STYLE[source.rank]} hover:border-foreground`}
    >
      {body}
    </a>
  );
}

/**
 * All sources of one claim: the most reliable first, the rest behind "+N".
 * Renders "No source" when the list is empty, so a missing source is visible.
 */
export function SourceBadges({ sources, max = 1 }: { sources: Source[]; max?: number }) {
  if (sources.length === 0) {
    return <span className={`${BASE} ${RANK_STYLE.UNKNOWN} italic`}>No source</span>;
  }
  const sorted = sortSources(sources);
  const shown = sorted.slice(0, max);
  const rest = sorted.slice(max);
  return (
    <span className="inline-flex flex-wrap items-center gap-1 align-middle">
      {shown.map((s, i) => (
        <SourceBadge key={`${s.url ?? s.name}-${i}`} source={s} />
      ))}
      {rest.length > 0 && (
        <details className="group inline-block">
          <summary
            className={`${BASE} ${RANK_STYLE.UNKNOWN} cursor-pointer list-none hover:text-foreground [&::-webkit-details-marker]:hidden`}
          >
            <span className="group-open:hidden">+{rest.length}</span>
            <span className="hidden group-open:inline">less</span>
          </summary>
          <span className="mt-1 flex flex-wrap gap-1">
            {rest.map((s, i) => (
              <SourceBadge key={`${s.url ?? s.name}-${i}`} source={s} />
            ))}
          </span>
        </details>
      )}
    </span>
  );
}
"use client";

// Funding amount (C18, B21): the optional amount field and the fit line on cards and checks.
// Founder side: "how much you want to raise"; investor side: "the most you will fund".

import { useState } from "react";

import { SourceBadges } from "@/components/SourceBadge";
import { formatEuro, parseEuro } from "@/lib/money";
import type { FundingFit, FundingVerdict } from "@/lib/types";

export type FundingSide = "founder" | "investor";

const LABEL: Record<FundingSide, Record<FundingVerdict, string>> = {
  founder: {
    fits: "Fits your raise",
    too_small: "Raise below their range",
    too_large: "Raise above their range",
    unknown: "Round sizes unknown",
  },
  investor: {
    fits: "Fits your check",
    too_small: "Raises less than your check",
    too_large: "Your check is a small share",
    unknown: "Round sizes unknown",
  },
};

// One accent (DESIGN.md): a fit is green, a mismatch is ink, unknown is faint.
const STYLE: Record<FundingVerdict, string> = {
  fits: "bg-echo border-moss text-foreground",
  too_small: "bg-background border-foreground text-foreground",
  too_large: "bg-background border-foreground text-foreground",
  unknown: "bg-background border-dashed border-line text-muted",
};

export function FundingFitLine({ fit, side }: { fit: FundingFit; side: FundingSide }) {
  return (
    <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
      <span className={`label rounded-[5px] border px-1.5 py-1 ${STYLE[fit.verdict]}`}>{LABEL[side][fit.verdict]}</span>
      <span className={fit.verdict === "unknown" ? "text-muted" : ""}>{fit.text}</span>
      {fit.sources.length > 0 && <SourceBadges sources={fit.sources} />}
    </div>
  );
}

/**
 * The optional amount: type "3M", "€500k" or "3 000 000". `onApply(null)` clears it.
 * Shows what will be sent (€3M) before it's applied, and an error for anything that isn't an amount.
 */
export function AmountField({
  side,
  value,
  onApply,
  disabled = false,
}: {
  side: FundingSide;
  value: number | null;
  onApply: (amount: number | null) => void;
  disabled?: boolean;
}) {
  const [text, setText] = useState(value ? formatEuro(value) : "");
  const parsed = parseEuro(text);
  const invalid = text.trim() !== "" && parsed === null;
  const label = side === "founder" ? "Amount you want to raise" : "Most you will fund";
  const id = `amount-${side}`;
  const changed = (parsed ?? null) !== value;

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (!invalid && changed) onApply(parsed);
      }}
    >
      <label htmlFor={id} className="label">
        {label} <span className="text-muted normal-case">(optional, EUR)</span>
      </label>
      <div className="mt-2 flex items-center gap-2">
        <input
          id={id}
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder={side === "founder" ? "e.g. 3M" : "e.g. 500k"}
          inputMode="decimal"
          autoComplete="off"
          aria-invalid={invalid}
          aria-describedby={`${id}-hint`}
          disabled={disabled}
          className="block h-10 w-44 rounded-[5px] border border-line bg-background px-3 outline-none placeholder:text-muted focus:border-foreground aria-[invalid=true]:border-foreground disabled:opacity-50"
        />
        <button type="submit" className="btn-ghost h-10" disabled={disabled || invalid || !changed}>
          {parsed === null && value !== null ? "Clear" : "Apply"}
        </button>
      </div>
      <p id={`${id}-hint`} className="mt-2 text-xs text-muted" aria-live="polite">
        {invalid
          ? "Type an amount like 3M, 500k or 3 000 000."
          : parsed !== null && changed
            ? `Compares ${formatEuro(parsed)} with the round sizes in Cala.`
            : side === "founder"
              ? "Compared with the sizes of the rounds each investor joins (whole rounds, not their share)."
              : "Compared with the sizes of this startup's rounds (whole rounds, not one investor's share)."}
      </p>
    </form>
  );
}
"use client";

// Shown under a loading state once it has taken a while. Uncached Cala queries
// take 20–80 s each (notes/A.md) and a cold founder report can need hundreds of
// them (notes/B.md), so a silent spinner would look broken.

import { useEffect, useState } from "react";

const STAGES: { after: number; text: string }[] = [
  { after: 8, text: "Still working. Cached companies load in seconds; a company we haven't seen before needs fresh Cala lookups." },
  { after: 45, text: "This company isn't cached yet, so every lookup goes to Cala. The first run can take several minutes; after that it's instant." },
  { after: 300, text: "Still going: this is a big one. Keep this tab open and it will appear when ready." },
];

export function SlowNotice() {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, []);
  const stage = [...STAGES].reverse().find((s) => seconds >= s.after);
  if (!stage) return null;
  return (
    <p className="mt-4 max-w-xl border-l-2 border-accent pl-3 text-sm" role="status">
      {stage.text} <span className="text-muted">({seconds} s)</span>
    </p>
  );
}

