"use client";

// Investor check (C7): verdict first (conflict or not), then the market map:
// the startup and each competitor with who backed it and its round history.

import Link from "next/link";
import { useEffect, useState } from "react";

import { ChatPanel } from "@/components/ChatPanel";
import { AmountField, FundingFitLine } from "@/components/FundingFit";
import { SlowNotice } from "@/components/SlowNotice";
import { SourceBadges } from "@/components/SourceBadge";
import { describeError } from "@/lib/errors";
import { checkInvestor } from "@/lib/api";
import { investorConflictText, marketMap, roundTitle, type MarketEntry } from "@/lib/check";
import { prettyEnum } from "@/lib/format";
import { founderPath } from "@/lib/routes";
import { formatSourceDate } from "@/lib/sources";
import type { InvestorCheck, Round } from "@/lib/types";

type Load =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean; detail: string | null }
  | { status: "ready"; check: InvestorCheck };

export function InvestorCheckView({
  investorId,
  companyId,
  initialMaxCheck = null,
}: {
  investorId: string;
  companyId: string;
  initialMaxCheck?: number | null; // ?check= in the URL (C18)
}) {
  const [load, setLoad] = useState<Load>({ status: "loading" });
  const [attempt, setAttempt] = useState(0); // "Try again" bumps this to refetch
  const [maxCheck, setMaxCheck] = useState<number | null>(initialMaxCheck); // the most the fund puts in (B21)
  const [updating, setUpdating] = useState(false); // a new amount is being checked; keep the page

  useEffect(() => {
    const ctrl = new AbortController();
    checkInvestor(
      { investor_id: investorId, company_id: companyId, ...(maxCheck ? { max_check_eur: maxCheck } : {}) },
      ctrl.signal,
    ).then(
      (check) => {
        if (ctrl.signal.aborted) return;
        setLoad({ status: "ready", check });
        setUpdating(false);
      },
      (err: unknown) => {
        if (ctrl.signal.aborted) return;
        const e = describeError(err);
        setLoad({ status: "error", message: e.message, notFound: e.notFound, detail: e.detail });
        setUpdating(false);
      },
    );
    return () => ctrl.abort();
  }, [investorId, companyId, attempt, maxCheck]);

  // A new amount is kept in the URL (?check=) and re-checked; the page stays while it loads.
  function applyMaxCheck(amount: number | null) {
    const url = new URL(window.location.href);
    if (amount) url.searchParams.set("check", String(amount));
    else url.searchParams.delete("check");
    window.history.replaceState(null, "", url);
    setUpdating(true);
    setMaxCheck(amount);
  }

  if (load.status === "loading") {
    return (
      <div aria-busy="true" aria-live="polite">
        <p className="label text-muted">Investor check</p>
        <div className="mt-4 h-20 w-2/3 max-w-xl animate-pulse bg-surface" />
        <p className="mt-8 max-w-xl text-muted">
          Comparing your portfolio with this startup&apos;s competitors in Cala, and pulling who
          backed each of them.
        </p>
        <SlowNotice />
      </div>
    );
  }
  if (load.status === "error") {
    return (
      <div className="max-w-xl">
        <p className="label text-muted">Investor check</p>
        <h1 className="display mt-4 text-5xl">
          {load.notFound ? "We couldn't check that pair." : "The check didn't load."}
        </h1>
        <p className="mt-6 border-l-2 border-foreground pl-3">{load.message}</p>
        {load.detail && (
          <details className="mt-3 text-sm text-muted">
            <summary className="cursor-pointer">Technical details</summary>
            <p className="mt-2 font-mono text-xs break-all">{load.detail}</p>
          </details>
        )}
        <div className="mt-8 flex gap-3">
          {!load.notFound && (
            <button
              type="button"
              className="btn-primary"
              onClick={() => {
                setLoad({ status: "loading" });
                setAttempt((n) => n + 1);
              }}
            >
              Try again
            </button>
          )}
          <Link href="/" className="btn-ghost h-[47px]">
            Search again
          </Link>
        </div>
      </div>
    );
  }

  const { check } = load;
  const { investor, company, conflicts } = check;
  const map = marketMap(check);
  const facts = [
    company.stage,
    company.country,
    ...company.industries.map(prettyEnum),
    company.total_funding_text && `${company.total_funding_text} raised`,
  ].filter(Boolean) as string[];

  return (
    <div>
      <title>{`${company.name} × ${investor.name} · Investor check · PitchSwitch`}</title>
      <ChatPanel
        companyId={company.id}
        investorId={investor.id}
        scope={`${investor.name} × ${company.name}`}
        suggestions={[
          `Does ${company.name} compete with anything ${investor.name} backs?`,
          `Who backed ${company.name}'s competitors?`,
          `Who led ${company.name}'s last round?`,
        ]}
      />
      <header>
        <p className="label text-muted">Investor check · as {investor.name}</p>
        <h1 className="display mt-4 text-5xl break-words sm:text-6xl md:text-8xl">{company.name}</h1>
        {facts.length > 0 && (
          <p className="label mt-6 flex flex-wrap gap-x-4 gap-y-1 text-muted">
            {facts.map((f) => (
              <span key={f}>{f}</span>
            ))}
          </p>
        )}
        {company.description && <p className="mt-4 max-w-2xl text-lg leading-snug">{company.description}</p>}
        <div className="mt-4 flex flex-wrap items-center gap-4">
          <SourceBadges sources={company.sources} />
          <Link href={founderPath(company.id)} className="text-sm underline underline-offset-4">
            Flip: see {company.name}&apos;s founder view
          </Link>
        </div>
      </header>

      {conflicts.length > 0 ? (
        <section className="mt-16 bg-press px-6 py-10 text-background md:px-10 md:py-14" aria-labelledby="verdict">
          <p className="label text-sage">Verdict</p>
          <h2 id="verdict" className="display mt-4 text-5xl md:text-7xl">
            Conflict.
          </h2>
          <ul className="mt-8 space-y-6">
            {conflicts.map((c, i) => (
              <li key={`${c.competitor.id}-${c.kind}-${i}`}>
                <p className="max-w-3xl text-xl leading-snug">{investorConflictText(c, company.name)}</p>
                <div className="mt-2">
                  <SourceBadges sources={c.sources} max={3} />
                </div>
              </li>
            ))}
          </ul>
        </section>
      ) : (
        <section className="mt-16 border-l-4 border-accent py-2 pl-6" aria-labelledby="verdict">
          <p className="label text-muted">Verdict</p>
          <h2 id="verdict" className="display mt-3 text-5xl md:text-6xl">
            No conflict found.
          </h2>
          <p className="mt-4 max-w-2xl text-muted">
            None of {company.name}&apos;s {check.competitors.length} competitors is in {investor.name}&apos;s
            portfolio in Cala, and no board links were found. Cala&apos;s portfolio data can be
            incomplete, so check anything that looks off.
          </p>
        </section>
      )}

      <section
        className={`mt-12 border-t border-line pt-8 transition-opacity ${updating ? "opacity-40" : ""}`}
        aria-label="Check size"
        aria-busy={updating}
      >
        <AmountField side="investor" value={maxCheck} onApply={applyMaxCheck} disabled={updating} />
        {maxCheck !== null && !updating && (
          <div className="mt-4">
            {check.funding_fit ? (
              <FundingFitLine fit={check.funding_fit} side="investor" />
            ) : (
              <p className="text-sm text-muted">
                Fit by round size isn&apos;t available on this server yet; it will show here once it is.
              </p>
            )}
          </div>
        )}
      </section>

      <section className="mt-20" aria-labelledby="map-heading">
        <p className="label text-muted">Market map · {check.competitors.length} competitors</p>
        <h2 id="map-heading" className="display mt-3 text-5xl md:text-6xl">
          Who backed the rivals
        </h2>
        <p className="mt-4 max-w-2xl text-muted">
          {company.name} and its competitors, with every investor Cala links to them and their
          round history. Leads are marked; your fund is highlighted.
        </p>
        <div className="mt-8">
          {map.map((e) => (
            <MarketCard key={e.company.id} entry={e} isStartup={e.company.id === company.id} investorId={investor.id} />
          ))}
        </div>
      </section>
    </div>
  );
}

function MarketCard({ entry, isStartup, investorId }: { entry: MarketEntry; isStartup: boolean; investorId: string }) {
  const { company, competitor, rounds, backers } = entry;
  const c = competitor?.company;
  const meta = c ? [c.stage, c.country].filter(Boolean).join(" · ") : "";
  return (
    <article className="grid gap-x-10 gap-y-4 border-t border-line py-8 md:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">
      <div>
        <p className="label text-muted">{isStartup ? "The startup" : competitor ? "Competitor" : "Other"}</p>
        <h3 className="mt-2 text-2xl font-medium tracking-tight">{company.name}</h3>
        {meta && <p className="label mt-2 text-muted">{meta}</p>}
        {competitor && (
          <p className="mt-3 text-sm leading-snug">
            {competitor.reason} <span className="label ml-1 text-muted">AI judgement</span>
          </p>
        )}
        {c && c.sources.length > 0 && (
          <div className="mt-3">
            <SourceBadges sources={c.sources} />
          </div>
        )}
      </div>

      <div>
        <p className="label">Backed by · {backers.length}</p>
        {backers.length === 0 ? (
          <p className="mt-2 text-sm text-muted">No investors in Cala.</p>
        ) : (
          <ul className="mt-2 flex flex-wrap gap-1.5">
            {backers.map((b) => {
              const you = b.investor.id === investorId;
              return (
                <li
                  key={b.investor.id}
                  className={`rounded-[5px] border px-2 py-1 text-sm ${
                    you ? "border-foreground bg-accent font-medium" : "border-line"
                  }`}
                >
                  {b.investor.name}
                  {b.led && <span className="label ml-1.5">Lead</span>}
                  {you && <span className="label ml-1.5">You</span>}
                </li>
              );
            })}
          </ul>
        )}

        <p className="label mt-6">Rounds · {rounds.length}</p>
        {rounds.length === 0 ? (
          <p className="mt-2 text-sm text-muted">No rounds in Cala.</p>
        ) : (
          <ul className="mt-2 divide-y divide-line border-y border-line">
            {rounds.map((r) => (
              <RoundRow key={r.id} round={r} investorId={investorId} />
            ))}
          </ul>
        )}
      </div>
    </article>
  );
}

function RoundRow({ round, investorId }: { round: Round; investorId: string }) {
  const date = formatSourceDate(round.date);
  const title = roundTitle(round);
  const unknown = title === "Round details unknown";
  return (
    <li className="py-3 text-sm">
      <p className="flex flex-wrap items-baseline gap-x-3">
        <span className={unknown ? "text-muted italic" : "font-medium"}>{title}</span>
        {date && <span className="text-muted">{date}</span>}
        {round.amount_text && <span>{round.amount_text}</span>}
      </p>
      {round.investors.length > 0 && (
        <p className="mt-1 text-muted">
          {round.investors.map((ri, i) => (
            <span key={ri.investor.id}>
              {i > 0 && ", "}
              <span className={ri.investor.id === investorId ? "font-medium text-foreground" : ""}>
                {ri.investor.name}
              </span>
              {ri.is_lead && " (lead)"}
            </span>
          ))}
        </p>
      )}
      <div className="mt-1.5">
        <SourceBadges sources={round.sources} />
      </div>
    </li>
  );
}
"use client";

// Investor brief (C10): one page on one investor for one company, every
// sentence citing [n] into the numbered source list below it. Printable.

import Link from "next/link";
import { useEffect, useState } from "react";

import { ChatPanel } from "@/components/ChatPanel";
import { BriefBody, InlineContent } from "@/components/CitedText";
import { SlowNotice } from "@/components/SlowNotice";
import { describeError } from "@/lib/errors";
import { getBrief } from "@/lib/api";
import { parseMarkdown, type Inline } from "@/lib/markdown";
import { checkPath, founderPath } from "@/lib/routes";
import type { Brief } from "@/lib/types";

type Load =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean; detail: string | null }
  | { status: "ready"; brief: Brief };

export function BriefView({
  investorId,
  companyId,
  names,
}: {
  investorId: string;
  companyId: string;
  names: { investor: string | null; company: string | null };
}) {
  const [load, setLoad] = useState<Load>({ status: "loading" });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    const ctrl = new AbortController();
    getBrief({ investor_id: investorId, company_id: companyId }, ctrl.signal).then(
      (brief) => {
        if (!ctrl.signal.aborted) setLoad({ status: "ready", brief });
      },
      (err: unknown) => {
        if (ctrl.signal.aborted) return;
        const e = describeError(err);
        setLoad({ status: "error", message: e.message, notFound: e.notFound, detail: e.detail });
      },
    );
    return () => ctrl.abort();
  }, [investorId, companyId, attempt]);

  if (load.status === "loading") {
    return (
      <div aria-busy="true" aria-live="polite">
        <p className="label text-muted">Investor brief</p>
        <div className="mt-4 h-16 w-2/3 max-w-xl animate-pulse bg-surface" />
        <p className="mt-8 max-w-xl text-muted">
          Gathering this investor&apos;s rounds, portfolio and sourced answers from Cala, then
          writing one page where every sentence cites its source.
        </p>
        <SlowNotice />
      </div>
    );
  }
  if (load.status === "error") {
    return (
      <div className="max-w-xl">
        <p className="label text-muted">Investor brief</p>
        <h1 className="display mt-4 text-5xl">
          {load.notFound ? "We couldn't brief that pair." : "The brief didn't load."}
        </h1>
        <p className="mt-6 border-l-2 border-foreground pl-3">{load.message}</p>
        {load.detail && (
          <details className="mt-3 text-sm text-muted">
            <summary className="cursor-pointer">Technical details</summary>
            <p className="mt-2 font-mono text-xs break-all">{load.detail}</p>
          </details>
        )}
        <div className="mt-8 flex gap-3">
          {!load.notFound && (
            <button
              type="button"
              className="btn-primary"
              onClick={() => {
                setLoad({ status: "loading" });
                setAttempt((n) => n + 1);
              }}
            >
              Try again
            </button>
          )}
          <Link href={founderPath(companyId)} className="btn-ghost h-[47px]">
            Back to the report
          </Link>
        </div>
      </div>
    );
  }

  const { brief } = load;
  const blocks = parseMarkdown(brief.markdown);
  const titleBlock = blocks[0]?.kind === "heading" && blocks[0].level === 1 ? blocks[0] : null;
  const body = titleBlock ? blocks.slice(1) : blocks;
  const hinted = names.investor && names.company ? `${names.investor} × ${names.company}` : null;
  const title = titleBlock ? plainText(titleBlock.content) : (hinted ?? "Investor brief");

  return (
    <article className="max-w-3xl">
      <title>{`${title} · Brief · PitchSwitch`}</title>
      <ChatPanel
        companyId={companyId}
        investorId={investorId}
        scope={title}
        suggestions={[
          "What else has this investor led in my space?",
          "Did they back any of my competitors?",
          "Should I pitch them, and why?",
        ]}
      />
      <div className="flex flex-wrap items-center justify-between gap-4 print:hidden">
        <p className="label text-muted">Investor brief · every sentence cites its source</p>
        <div className="flex flex-wrap items-center gap-4 text-sm">
          <Link href={founderPath(companyId)} className="underline underline-offset-4">
            Founder report
          </Link>
          <Link href={checkPath(investorId, companyId)} className="underline underline-offset-4">
            Investor&apos;s view
          </Link>
          <button type="button" onClick={() => window.print()} className="btn-ghost h-9">
            Print
          </button>
        </div>
      </div>
      <h1 className="display mt-4 text-5xl break-words sm:text-6xl md:text-7xl">
        {titleBlock ? <InlineContent nodes={titleBlock.content} citations={brief.citations} /> : title}
      </h1>

      <BriefBody blocks={body} citations={brief.citations} anchor="cite" />
    </article>
  );
}

function plainText(nodes: Inline[]): string {
  return nodes
    .map((n) => (n.kind === "text" ? n.text : n.kind === "cite" ? "" : plainText(n.children)))
    .join("")
    .trim();
}
"use client";

// Chat panel (C12): ask follow-up questions on a report, check or brief page.
// Answers stream from /api/chat, scoped to the page's company / investor; every
// sentence cites a Cala fact. The contract has no history: each question stands
// alone, so the thread is just a list of independent Q&As.

import { useEffect, useRef, useState } from "react";

import { InlineContent } from "@/components/CitedText";
import { SourceBadge } from "@/components/SourceBadge";
import { describeError } from "@/lib/errors";
import { chat } from "@/lib/api";
import { applyChatEvent, emptyAnswer, type ChatAnswer } from "@/lib/chat";
import { parseInline } from "@/lib/markdown";
import { safeUrl } from "@/lib/sources";

interface Turn {
  id: number;
  question: string;
  answer: ChatAnswer;
}

export function ChatPanel({
  companyId,
  investorId,
  scope,
  suggestions,
}: {
  companyId?: string;
  investorId?: string;
  scope: string; // e.g. "Sensofusion Oy" or "Rainfall Ventures × Sensofusion Oy"
  suggestions: string[];
}) {
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState("");
  const [turns, setTurns] = useState<Turn[]>([]);
  const [busy, setBusy] = useState(false);
  const abort = useRef<AbortController | null>(null);
  const nextId = useRef(1);
  const endRef = useRef<HTMLDivElement | null>(null);
  const inputRef = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => () => abort.current?.abort(), []);
  // Block body on purpose: newer Chrome's scrollIntoView returns a value, and an expression body
  // would hand it to React as the effect's cleanup, which React then calls ("i is not a function").
  useEffect(() => {
    endRef.current?.scrollIntoView({ block: "end" });
  }, [turns]);
  useEffect(() => {
    if (!open) return;
    inputRef.current?.focus();
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  async function ask(question: string) {
    const q = question.trim();
    if (!q || busy) return;
    const id = nextId.current++;
    const ctrl = new AbortController();
    abort.current = ctrl;
    setInput("");
    setBusy(true);
    setTurns((t) => [...t, { id, question: q, answer: emptyAnswer() }]);
    const update = (f: (a: ChatAnswer) => ChatAnswer) =>
      setTurns((t) => t.map((x) => (x.id === id ? { ...x, answer: f(x.answer) } : x)));
    try {
      for await (const e of chat(
        { message: q, ...(companyId ? { company_id: companyId } : {}), ...(investorId ? { investor_id: investorId } : {}) },
        ctrl.signal,
      )) {
        update((a) => applyChatEvent(a, e));
      }
      update((a) => (a.done || a.error ? a : { ...a, done: true }));
    } catch (err) {
      if (!ctrl.signal.aborted) {
        update((a) => ({ ...a, error: describeError(err).message }));
      } else {
        update((a) => ({ ...a, error: a.error ?? "Stopped." }));
      }
    } finally {
      setBusy(false);
    }
  }

  return (
    <>
      {!open && (
        <button
          type="button"
          onClick={() => setOpen(true)}
          className="btn-primary fixed right-5 bottom-5 z-30 print:hidden"
          aria-haspopup="dialog"
        >
          Ask about this
        </button>
      )}
      {open && (
        <aside
          role="dialog"
          aria-label={`Ask about ${scope}`}
          className="fixed inset-0 z-40 flex flex-col border-line bg-background sm:inset-y-0 sm:right-0 sm:left-auto sm:w-[28rem] sm:border-l print:hidden"
        >
          <header className="flex items-start justify-between gap-4 border-b border-line px-5 py-4">
            <div className="min-w-0">
              <p className="label text-muted">Ask · answers cite Cala</p>
              <p className="mt-1 truncate font-medium">{scope}</p>
            </div>
            <button type="button" onClick={() => setOpen(false)} className="label text-muted hover:text-foreground">
              Close
            </button>
          </header>

          <div className="flex-1 overflow-y-auto px-5 py-5">
            {turns.length === 0 ? (
              <div>
                <p className="text-muted">
                  Ask anything about {scope}. Each question is answered on its own, from Cala facts
                  only; every sentence links to its source.
                </p>
                <ul className="mt-5 space-y-2">
                  {suggestions.map((s) => (
                    <li key={s}>
                      <button
                        type="button"
                        onClick={() => void ask(s)}
                        className="w-full rounded-[5px] border border-line px-3 py-2 text-left text-sm hover:border-foreground"
                      >
                        {s}
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            ) : (
              <ol className="space-y-8">
                {turns.map((t) => (
                  <li key={t.id}>
                    <TurnView turn={t} />
                  </li>
                ))}
              </ol>
            )}
            <div ref={endRef} />
          </div>

          <form
            className="border-t border-line p-4"
            onSubmit={(e) => {
              e.preventDefault();
              void ask(input);
            }}
          >
            <label htmlFor="chat-input" className="sr-only">
              Your question
            </label>
            <div className="flex items-end gap-2">
              <textarea
                id="chat-input"
                ref={inputRef}
                rows={2}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    void ask(input);
                  }
                }}
                placeholder="e.g. Who led their last round?"
                className="min-w-0 flex-1 resize-none rounded-[5px] border border-line bg-background p-2.5 outline-none placeholder:text-muted focus:border-foreground"
              />
              {busy ? (
                <button type="button" className="btn-ghost h-11" onClick={() => abort.current?.abort()}>
                  Stop
                </button>
              ) : (
                <button type="submit" className="btn-ghost h-11" disabled={!input.trim()}>
                  Ask
                </button>
              )}
            </div>
          </form>
        </aside>
      )}
    </>
  );
}

function TurnView({ turn }: { turn: Turn }) {
  const { question, answer, id } = turn;
  const anchor = `chat-${id}-cite`;
  const waiting = !answer.text && !answer.done && !answer.error;
  return (
    <article>
      <p className="border-l-2 border-accent pl-3 font-medium">{question}</p>
      {waiting && (
        <p className="mt-3 text-sm text-muted" aria-live="polite">
          {answer.steps.at(-1) ?? "Thinking"}
          <span className="ml-1 inline-block animate-pulse">…</span> <Elapsed />
        </p>
      )}
      {answer.text && (
        <p className="mt-3 leading-relaxed">
          <InlineContent nodes={parseInline(answer.text)} citations={answer.citations} anchor={anchor} />
        </p>
      )}
      {answer.done && !answer.text && !answer.error && (
        <p className="mt-3 text-muted">No sourced answer came back for this question.</p>
      )}
      {answer.error && <p className="mt-3 border-l-2 border-foreground pl-3 text-sm">{answer.error}</p>}
      {answer.citations.length > 0 && (
        <ol className="mt-3 space-y-1.5">
          {answer.citations.map((s, i) => {
            const href = safeUrl(s.url);
            return (
              <li key={i} id={`${anchor}-${i + 1}`} className="flex min-w-0 scroll-mt-4 items-center gap-2 text-xs target:bg-echo">
                <span className="w-4 shrink-0 text-right text-muted">{i + 1}</span>
                <SourceBadge source={s} />
                {href ? (
                  <a href={href} target="_blank" rel="noopener noreferrer" className="min-w-0 truncate underline underline-offset-2">
                    {s.name}
                  </a>
                ) : (
                  <span className="min-w-0 truncate">{s.name}</span>
                )}
              </li>
            );
          })}
        </ol>
      )}
    </article>
  );
}

/** Seconds since this waiting line appeared: answers that need Cala's sourced search can take a minute or two. */
function Elapsed() {
  const [s, setS] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setS((n) => n + 1), 1000);
    return () => clearInterval(t);
  }, []);
  if (s < 5) return null;
  return (
    <span className="whitespace-nowrap">
      ({s} s{s >= 30 ? "; questions that need Cala's sourced search can take a minute or two" : ""})
    </span>
  );
}

